// One item per Typeform submission.
// The keys on the left are YOUR question titles, the values are what HubSpot expects.
const SEGMENTS = {
  '[ANSWER OPTION A]': '[HUBSPOT LIST ID A]',
  '[ANSWER OPTION B]': '[HUBSPOT LIST ID B]',
  '[ANSWER OPTION C]': '[HUBSPOT LIST ID C]'
};
const DEFAULT_LIST = '[HUBSPOT LIST ID DEFAULT]';

const pick = (a, keys) => {
  for (const k of keys) {
    if (a[k] !== undefined && String(a[k]).trim() !== '') return String(a[k]).trim();
  }
  return '';
};

const out = [];
for (const item of $input.all()) {
  const a = item.json;
  const email = pick(a, ['Email', 'Your email', 'What is your email address?']).toLowerCase();
  const full = pick(a, ['Name', 'Your name', 'What is your name?']);
  const parts = full.split(' ').filter(Boolean);
  const interest = pick(a, ['[YOUR SEGMENT QUESTION TITLE]', 'What are you looking for?']);
  const matched = Object.keys(SEGMENTS).find(k => interest.toLowerCase() === k.toLowerCase());
  out.push({
    json: {
      email,
      firstName: parts[0] || '',
      lastName: parts.slice(1).join(' '),
      phone: pick(a, ['Phone', 'Phone number', 'Your phone number']),
      company: pick(a, ['Company', 'Company name', 'Your company']),
      interest,
      listId: matched ? SEGMENTS[matched] : DEFAULT_LIST,
      raw: JSON.stringify(a),
      submittedAt: new Date().toISOString()
    }
  });
}
return out;

